def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(value):
        if isinstance(value, int):
            if value < 0:
                raise ValueError
            if value <= 24:
                return value * 60
            return value
        text = str(value).strip()
        if text == "":
            raise ValueError
        low = text.lower()
        if ":" in text:
            parts = text.split(":", 1)
            hour_text = ""
            for ch in parts[0]:
                if ch.isdigit():
                    hour_text += ch
            minute_text = ""
            for ch in parts[1]:
                if ch.isdigit():
                    minute_text += ch
                else:
                    break
            if hour_text == "" or minute_text == "":
                raise ValueError
            hour = int(hour_text)
            minute = int(minute_text[:2])
            if "pm" in low and hour < 12:
                hour += 12
            if "am" in low and hour == 12:
                hour = 0
            return hour * 60 + minute
        if text.isdigit():
            if len(text) <= 2:
                return int(text) * 60
            if len(text) == 3:
                return int(text[0]) * 60 + int(text[1:])
            return int(text[:2]) * 60 + int(text[2:4])
        raise ValueError

    def format_time(total_minutes):
        hour = total_minutes // 60
        minute = total_minutes % 60
        if hour < 10:
            hour_text = "0" + str(hour)
        else:
            hour_text = str(hour)
        if minute < 10:
            minute_text = "0" + str(minute)
        else:
            minute_text = str(minute)
        return hour_text + ":" + minute_text

    def round_up_quarter(value):
        return ((value + 14) // 15) * 15

    def parse_hours(value):
        if isinstance(value, dict):
            start = None
            end = None
            for key in ("start", "start_time", "begin", "from"):
                if key in value:
                    start = value[key]
                    break
            for key in ("end", "end_time", "finish", "to"):
                if key in value:
                    end = value[key]
                    break
            if start is not None and end is not None:
                try:
                    return parse_time(start), parse_time(end)
                except Exception:
                    pass
        elif isinstance(value, str):
            text = value.strip()
            if "-" in text:
                left, right = text.split("-", 1)
                try:
                    return parse_time(left), parse_time(right)
                except Exception:
                    pass
        elif isinstance(value, list) or isinstance(value, tuple):
            if len(value) >= 2:
                try:
                    return parse_time(value[0]), parse_time(value[1])
                except Exception:
                    pass
        return 0, 24 * 60

    def text_times(text):
        found = []
        if not isinstance(text, str):
            text = str(text)
        n = len(text)
        i = 0
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and text[j].isdigit():
                    j += 1
                if j < n and text[j] == ":" and j + 2 < n and text[j + 1].isdigit() and text[j + 2].isdigit():
                    end = j + 3
                    while end < n and text[end] == " ":
                        end += 1
                    if end + 1 < n and text[end:end + 2].lower() in ("am", "pm"):
                        end += 2
                    token = text[i:end]
                    try:
                        found.append(parse_time(token))
                    except Exception:
                        pass
                    i = end
                    continue
            i += 1
        return found

    def event_bounds(event):
        if isinstance(event, dict):
            if str(event.get("show_as", "")).lower() == "free":
                return None
            start = None
            end = None
            for key in ("start", "start_time", "startTime", "begin", "from"):
                if key in event:
                    start = event[key]
                    break
            for key in ("end", "end_time", "endTime", "finish", "to"):
                if key in event:
                    end = event[key]
                    break
            if start is not None and end is not None:
                try:
                    return parse_time(start), parse_time(end)
                except Exception:
                    pass
            times = text_times(str(event))
            if len(times) >= 2:
                return times[0], times[1]
        elif isinstance(event, list) or isinstance(event, tuple):
            if len(event) >= 2:
                try:
                    return parse_time(event[0]), parse_time(event[1])
                except Exception:
                    pass
            times = text_times(str(event))
            if len(times) >= 2:
                return times[0], times[1]
        elif isinstance(event, str):
            low = event.lower()
            if "free" in low and "busy" not in low:
                return None
            times = text_times(event)
            if len(times) >= 2:
                return times[0], times[1]
        return None

    def get_day_data(cal, day):
        if isinstance(cal, dict) and "days" in cal and isinstance(cal["days"], list):
            for item in cal["days"]:
                if isinstance(item, dict) and item.get("day") == day:
                    return item
        return cal

    def get_events(cal, day):
        day_data = get_day_data(cal, day)
        if isinstance(day_data, dict):
            if "events" in day_data:
                items = day_data["events"]
            elif "busy" in day_data:
                items = day_data["busy"]
            else:
                items = []
            if items is None:
                return []
            if isinstance(items, dict):
                return [items]
            if isinstance(items, list) or isinstance(items, tuple):
                return list(items)
            return [items]
        if isinstance(day_data, list) or isinstance(day_data, tuple):
            return list(day_data)
        if isinstance(day_data, str):
            return [day_data]
        return []

    def get_working_hours(cal, day_data):
        values = []
        if isinstance(day_data, dict):
            if "working_hours" in day_data:
                values.append(day_data["working_hours"])
            if "workingHours" in day_data:
                values.append(day_data["workingHours"])
        if isinstance(cal, dict):
            if "working_hours" in cal:
                values.append(cal["working_hours"])
            if "workingHours" in cal:
                values.append(cal["workingHours"])
        for value in values:
            start, end = parse_hours(value)
            if end > start:
                return start, end
        return 0, 24 * 60

    people = [""]
    for name in attendees:
        people.append(name)

    start_results = {}

    for day in days:
        busy = []
        common_start = 0
        common_end = 24 * 60
        first_person = True

        for person in people:
            cal = api.read_calendar(person, day)
            day_data = get_day_data(cal, day)
            work_start, work_end = get_working_hours(cal, day_data)
            if work_start < 0:
                work_start = 0
            if work_end < 0:
                work_end = 0
            if work_start > 24 * 60:
                work_start = 24 * 60
            if work_end > 24 * 60:
                work_end = 24 * 60

            if first_person:
                common_start = work_start
                common_end = work_end
                first_person = False
            else:
                if work_start > common_start:
                    common_start = work_start
                if work_end < common_end:
                    common_end = work_end

            for event in get_events(cal, day):
                bounds = event_bounds(event)
                if bounds is None:
                    continue
                s, e = bounds
                if e <= s:
                    continue
                if e <= 0 or s >= 24 * 60:
                    continue
                if s < 0:
                    s = 0
                if e > 24 * 60:
                    e = 24 * 60
                if e > s:
                    busy.append((s, e))

        if common_end <= common_start:
            continue

        if earliest != "":
            start_limit = parse_time(earliest)
        else:
            start_limit = 0
        if start_limit < common_start:
            start_limit = common_start
        start_limit = round_up_quarter(start_limit)

        if latest_end != "":
            end_limit = parse_time(latest_end)
        else:
            end_limit = common_end
        if end_limit > common_end:
            end_limit = common_end

        upper = end_limit - minutes
        if upper > common_end - minutes:
            upper = common_end - minutes
        upper = (upper // 15) * 15

        if upper < start_limit:
            continue

        if len(busy) > 0:
            busy = sorted(busy)
            merged = [list(busy[0])]
            for s, e in busy[1:]:
                if s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
        else:
            merged = []

        slots = []
        current = start_limit
        while current <= upper:
            meeting_end = current + minutes
            free = True
            for s, e in merged:
                if s >= meeting_end:
                    break
                if e > current and s < meeting_end:
                    free = False
                    break
            if free:
                slots.append(format_time(current))
            current += 15

        if len(slots) > 0:
            start_results[day] = slots

    return {"starts": start_results}
