    def parseTime(value):
        if isinstance(value, dict):
            for key in ("time", "dateTime", "datetime", "value", "start", "end", "from", "to"):
                if key in value:
                    try:
                        return parseTime(value[key])
                    except Exception:
                        pass
            for item in value.values():
                try:
                    return parseTime(item)
                except Exception:
                    pass
            raise ValueError

        if isinstance(value, list) or isinstance(value, tuple):
            if len(value) > 0:
                return parseTime(value[0])
            raise ValueError

        if isinstance(value, int):
            if value < 0:
                raise ValueError
            if value < 24:
                return value * 60
            if value == 2400:
                return 24 * 60
            if value <= 2359:
                hour = value // 100
                minute = value % 100
                if 0 <= hour < 24 and 0 <= minute < 60:
                    return hour * 60 + minute
            raise ValueError

        text = str(value).strip().lower()
        if text == "":
            raise ValueError

        suffix = ""
        if text.endswith("am") or text.endswith("pm"):
            suffix = text[-2:]
            text = text[:-2].strip()

        if ":" in text:
            parts = text.split(":")
            if len(parts) < 2:
                raise ValueError
            hourText = ""
            for ch in parts[0]:
                if ch.isdigit():
                    hourText += ch
            minuteText = ""
            for ch in parts[1]:
                if ch.isdigit():
                    minuteText += ch
                else:
                    break
            if hourText == "" or minuteText == "":
                raise ValueError
            hour = int(hourText)
            minute = int(minuteText[:2])
        elif text.isdigit():
            if len(text) <= 2:
                hour = int(text)
                minute = 0
            elif len(text) == 3:
                hour = int(text[0])
                minute = int(text[1:])
            else:
                hour = int(text[:-2])
                minute = int(text[-2:])
        else:
            raise ValueError

        if suffix == "pm" and hour < 12:
            hour += 12
        if suffix == "am" and hour == 12:
            hour = 0

        if hour < 0 or minute < 0 or minute >= 60 or hour > 24 or (hour == 24 and minute > 0):
            raise ValueError

